Algorithm FichaDeLucia
  Define edad As Integer <- 11;
  Define altura As Real <- 1.42;
  Define inicial As Character <- 'L';
  Define nombre As String <- "Lucía";
  Define aprobada As Boolean <- True;
  Write nombre + " (" + inicial + ")";
  Write edad, " años, ", altura, " m";
  Write aprobada;
EndAlgorithm

Algorithm Precios
  Define precio As Real <- 7;
  Write precio;
  Write 0.1 + 0.2;
EndAlgorithm

Algorithm Textos
  Define cara As Character <- "😀";
  Write length(""), " ", length("año"), " ", charAt("Hola", 0);
  Write cara, " ", charCode(cara), " ", charFromCode(76);
EndAlgorithm

Algorithm Conversiones
  Define nota As Real <- -8.7;
  Write trunc(nota), " ", round(nota), " ", toText(1.5) + "!";
EndAlgorithm

Algorithm Desborde
  Define grande As Integer <- 9223372036854775807;
  Write grande + 1;
EndAlgorithm

Algorithm Comparar
  Define a As Real <- 0.1 + 0.2;
  If a = 0.3 Then
    Write "iguales";
  Else
    Write "distintos";
  EndIf
EndAlgorithm

Algorithm SinPerder
  Define cantidad As Integer <- 2.5;
EndAlgorithm
